// Função nativa simples para gerar hash numérico em string sem bibliotecas externas
function gerarHashSimples(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Converte para inteiro de 32 bits
  }
  return 'job_' + Math.abs(hash).toString(16);
}

// Obtém os parâmetros definidos no nó 'Meu Perfil'
const perfil = $('Meu Perfil').first().json;
const palavrasProibidas = (perfil.palavras_proibidas || []).map(p => p.toLowerCase());

const vagasProcessadas = [];

for (const item of $input.all()) {
  const vaga = item.json;

  // 1. Gera a chave e o identificador canónico de deduplicação
  const empresaLimpa = (vaga.empresa || '').trim().toLowerCase();
  const tituloLimpo = (vaga.titulo || '').trim().toLowerCase();
  const localizacaoLimpa = (vaga.localizacao || '').trim().toLowerCase();

  const rawKey = `${empresaLimpa}_${tituloLimpo}_${localizacaoLimpa}`;
  const hash = gerarHashSimples(rawKey);

  // 2. Verificação de termos proibidos no título
  const possuiTermoProibido = palavrasProibidas.some(termo => tituloLimpo.includes(termo));

  let aprovadaNaTriagem = true;
  let motivoDescarte = null;

  if (possuiTermoProibido) {
    aprovadaNaTriagem = false;
    motivoDescarte = "Título contém termo proibido pela senioridade";
  }

  // 3. Estruturação dos dados
  vagasProcessadas.push({
    json: {
      hash_dedup: hash,
      titulo: vaga.titulo,
      empresa: vaga.empresa,
      localizacao: vaga.localizacao,
      modelo_trabalho: vaga.modelo_trabalho,
      senioridade_declarada: vaga.senioridade,
      url_original: vaga.url,
      fonte: vaga.fonte,
      descricao_raw: vaga.descricao,
      aprovada_triagem: aprovadaNaTriagem,
      motivo_descarte: motivoDescarte
    }
  });
}

return vagasProcessadas;

