for (const item of $input.all()) {
  // Pega o texto exatamente na estrutura retornada pelo nó do Gemini
  let rawText = '';

  if (item.json.content?.parts?.[0]?.text) {
    rawText = item.json.content.parts[0].text;
  } else if (typeof item.json.text === 'string') {
    rawText = item.json.text;
  } else if (item.json.candidates?.[0]?.content?.parts?.[0]?.text) {
    rawText = item.json.candidates[0].content.parts[0].text;
  } else {
    rawText = String(item.json.text || item.json.content || '');
  }

  // Remove eventuais marcações de markdown ```json
  rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

  let parsed = {};
  try {
    parsed = JSON.parse(rawText);
  } catch (e) {
    parsed = {
      score_match: 50,
      nivel_aderencia: 'MEDIO',
      pontos_fortes: [],
      gaps: ['Falha no parser JSON'],
      requisitos_eliminatorios: [],
      justificativa: 'Não foi possível interpretar a resposta estruturada.'
    };
  }

  // Atribui os campos calculados para gravação no banco
  item.json.score_match = parsed.score_match;
  item.json.nivel_aderencia = parsed.nivel_aderencia;
  item.json.pontos_fortes = parsed.pontos_fortes;
  item.json.gaps = parsed.gaps;
  item.json.requisitos_eliminatorios = parsed.requisitos_eliminatorios;
  item.json.justificativa = parsed.justificativa;
}

return $input.all();

